import { readVeryfrontCloudModelFacts, registerVeryfrontCloudModelFacts, } from "../../provider/veryfront-cloud/model-catalog.js";
const createObject = Object.create;
/** @internal Each retry reads current lease authority without exposing its credential. */
export function createRenewingLocalModel(readCredential, build) {
    let credential = readCredential();
    let model = build(credential);
    const current = () => {
        const next = readCredential();
        if (next !== credential) {
            model = build(next);
            credential = next;
        }
        return model;
    };
    const initialFacts = readVeryfrontCloudModelFacts(model);
    const wrapped = createObject(model, {
        doStream: {
            value: (options) => current().doStream(options),
        },
        doGenerate: {
            value: (options) => current().doGenerate(options),
        },
        prepare: {
            value: async (signal) => {
                await current().prepare?.(signal);
            },
        },
    });
    if (initialFacts) {
        registerVeryfrontCloudModelFacts(wrapped, () => readVeryfrontCloudModelFacts(current()) ?? initialFacts);
    }
    return wrapped;
}
